package com.dukaops.backend.settings;
import java.util.UUID; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import com.dukaops.backend.auth.*; import com.dukaops.backend.branch.*; import com.dukaops.backend.settings.dto.*; import com.dukaops.backend.tenant.*;
@Service public class SettingsService { private final TenantRepository tenants; private final BranchRepository branches; public SettingsService(TenantRepository t,BranchRepository b){tenants=t;branches=b;} private void admin(TenantUserPrincipal p){if(p.getRole()!=UserRole.OWNER&&p.getRole()!=UserRole.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only owners and administrators can update business settings.");} private Tenant tenant(TenantUserPrincipal p){return tenants.findById(p.getTenantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Business not found."));} private BusinessSettingsResponse response(Tenant t){var b=t.getDefaultBranch();return new BusinessSettingsResponse(t.getId(),t.getName(),t.getSlug(),t.getBusinessEmail(),t.getBusinessPhone(),t.getBusinessAddress(),t.getCurrency(),t.getTimezone(),t.getDateFormat(),b==null?null:b.getId(),b==null?null:b.getName(),t.getUpdatedAt());}
 @Transactional(readOnly=true) public BusinessSettingsResponse get(TenantUserPrincipal p){return response(tenant(p));} @Transactional public BusinessSettingsResponse update(TenantUserPrincipal p,BusinessSettingsRequest r){admin(p);PreferencesValidation.validate(r.currency(),r.timezone(),r.dateFormat());Tenant t=tenant(p);Branch b=null;if(r.defaultBranchId()!=null)b=branches.findTenantScopedBranchById(r.defaultBranchId(),p.getTenantId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Default branch must belong to your business."));t.updateSettings(clean(r.businessEmail()),clean(r.businessPhone()),clean(r.businessAddress()),r.currency().trim().toUpperCase(),r.timezone().trim(),r.dateFormat().trim(),b);return response(t);} private String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
 @Transactional(readOnly=true) public PreferencesResponse preferences(TenantUserPrincipal principal) {
     var current = get(principal);
     return new PreferencesResponse(current.currency(), current.timezone(), current.dateFormat(), current.defaultBranchId(), current.defaultBranchName());
 }
 @Transactional public PreferencesResponse updatePreferences(TenantUserPrincipal principal, PreferencesRequest request) {
     admin(principal);
     var current = get(principal);
     update(principal, new BusinessSettingsRequest(current.businessEmail(), current.businessPhone(), current.businessAddress(), request.currency(), request.timezone(), request.dateFormat(), request.defaultBranchId()));
     return preferences(principal);
 }
